CREATE SCHEMA IF NOT EXISTS admin; CREATE SCHEMA IF NOT EXISTS stage; CREATE SCHEMA IF NOT EXISTS raw; CREATE SCHEMA IF NOT EXISTS reporting;
CREATE TABLE IF NOT EXISTS admin.file_inventory(file_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,file_name VARCHAR(255) NOT NULL,file_path TEXT NOT NULL,sw_i_step VARCHAR(100),file_size_bytes BIGINT NOT NULL,file_hash CHAR(64) NOT NULL,received_datetime TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,processing_start_time TIMESTAMPTZ,processing_end_time TIMESTAMPTZ,process_status VARCHAR(30) NOT NULL DEFAULT 'Pending',error_message TEXT,CHECK(process_status IN('Pending','Processing','Completed','Failed','Rejected','Duplicate')));
CREATE UNIQUE INDEX IF NOT EXISTS ux_file_inventory_hash ON admin.file_inventory(file_hash);
CREATE TABLE IF NOT EXISTS admin.process_execution_log(process_run_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,file_id BIGINT REFERENCES admin.file_inventory(file_id),process_name VARCHAR(200) NOT NULL,start_time TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,end_time TIMESTAMPTZ,files_processed INT NOT NULL DEFAULT 0,report_records_loaded INT NOT NULL DEFAULT 0,ecu_records_loaded INT NOT NULL DEFAULT 0,dtc_records_loaded INT NOT NULL DEFAULT 0,environment_records_loaded INT NOT NULL DEFAULT 0,rejected_records INT NOT NULL DEFAULT 0,process_status VARCHAR(30) NOT NULL DEFAULT 'Started',error_message TEXT,CHECK(process_status IN('Started','Completed','CompletedWithWarnings','Failed','Rejected')));
CREATE TABLE IF NOT EXISTS admin.data_quality_issue(quality_issue_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,process_run_id BIGINT NOT NULL REFERENCES admin.process_execution_log(process_run_id),file_id BIGINT REFERENCES admin.file_inventory(file_id),source_table VARCHAR(100) NOT NULL,source_row_id BIGINT,rule_code VARCHAR(50) NOT NULL,field_name VARCHAR(100),invalid_value TEXT,issue_description TEXT NOT NULL,severity VARCHAR(20) NOT NULL,created_datetime TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(severity IN('Information','Warning','Error','Critical')));
CREATE TABLE IF NOT EXISTS stage.diagnostic_report(stage_report_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,process_run_id BIGINT NOT NULL REFERENCES admin.process_execution_log(process_run_id),file_id BIGINT NOT NULL REFERENCES admin.file_inventory(file_id),file_name VARCHAR(255),file_path TEXT,vin VARCHAR(64),sw_i_step VARCHAR(100),sa_codes TEXT,load_datetime TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stage.ecu_version(stage_ecu_version_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,process_run_id BIGINT NOT NULL REFERENCES admin.process_execution_log(process_run_id),file_id BIGINT NOT NULL REFERENCES admin.file_inventory(file_id),file_name VARCHAR(255),sw_i_step VARCHAR(100),ecu_name VARCHAR(100),hardware_version VARCHAR(100),bootloader_version VARCHAR(100),sw_version VARCHAR(100),coding VARCHAR(100),diagnostic_address VARCHAR(50),calibration_version VARCHAR(100),network VARCHAR(100),secure_boot VARCHAR(50),ota_state VARCHAR(50),load_datetime TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stage.dtc_event(stage_dtc_event_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,process_run_id BIGINT NOT NULL REFERENCES admin.process_execution_log(process_run_id),file_id BIGINT NOT NULL REFERENCES admin.file_inventory(file_id),source_row_number INT NOT NULL,file_name VARCHAR(255),sw_i_step VARCHAR(100),ecu_name VARCHAR(100),dtc_code VARCHAR(50),description TEXT,fault_category VARCHAR(100),status VARCHAR(50),occurrence_counter INT,aging_counter INT,priority INT,event_timestamp TIMESTAMPTZ,risk_score INT,load_datetime TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stage.environment_signal(stage_signal_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,process_run_id BIGINT NOT NULL REFERENCES admin.process_execution_log(process_run_id),file_id BIGINT NOT NULL REFERENCES admin.file_inventory(file_id),source_row_number INT NOT NULL,file_name VARCHAR(255),sw_i_step VARCHAR(100),ecu_name VARCHAR(100),dtc_code VARCHAR(50),signal_name VARCHAR(200),signal_value TEXT,event_timestamp TIMESTAMPTZ,load_datetime TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS raw.diagnostic_report(report_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,file_id BIGINT NOT NULL UNIQUE REFERENCES admin.file_inventory(file_id),file_name VARCHAR(255) NOT NULL,file_path TEXT,vin VARCHAR(64),sw_i_step VARCHAR(100) NOT NULL,sa_codes TEXT,created_datetime TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS raw.ecu_version(ecu_version_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,report_id BIGINT NOT NULL REFERENCES raw.diagnostic_report(report_id),ecu_name VARCHAR(100) NOT NULL,hardware_version VARCHAR(100),bootloader_version VARCHAR(100),sw_version VARCHAR(100),coding VARCHAR(100),diagnostic_address VARCHAR(50),calibration_version VARCHAR(100),network VARCHAR(100),secure_boot VARCHAR(50),ota_state VARCHAR(50),UNIQUE(report_id,ecu_name));
CREATE TABLE IF NOT EXISTS raw.dtc_event(dtc_event_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,report_id BIGINT NOT NULL REFERENCES raw.diagnostic_report(report_id),source_row_number INT NOT NULL,ecu_name VARCHAR(100) NOT NULL,dtc_code VARCHAR(50) NOT NULL,description TEXT NOT NULL,fault_category VARCHAR(100) NOT NULL,status VARCHAR(50) NOT NULL,occurrence_counter INT NOT NULL,aging_counter INT NOT NULL,priority INT NOT NULL,event_timestamp TIMESTAMPTZ NOT NULL,risk_score INT NOT NULL,CHECK(status IN('Active','Stored','Intermittent')),CHECK(priority BETWEEN 1 AND 5),CHECK(occurrence_counter>=0),CHECK(aging_counter>=0),UNIQUE(report_id,source_row_number));
CREATE TABLE IF NOT EXISTS raw.environment_signal(environment_signal_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,dtc_event_id BIGINT NOT NULL REFERENCES raw.dtc_event(dtc_event_id),source_row_number INT NOT NULL,signal_name VARCHAR(200) NOT NULL,signal_value TEXT,numeric_signal_value NUMERIC(18,4),event_timestamp TIMESTAMPTZ NOT NULL,UNIQUE(dtc_event_id,source_row_number));
